insert into public.events (slug, title, short_description, description, category, is_published, is_featured, media)
values
  ('noche-de-flores', 'Noche de Flores', 'Mexican Night', 'A Mexican-inspired night with orange marigolds, red and ivory papel picado and violet light. Choose an original floral, half-face or calavera design at the face-paint station. The DJ moves from Mexican favourites to Spanish-language dance tracks and a marigold disco finale.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#ff963b","secondaryColor":"#541738","surface":"dark","channels":["events"]}}'::jsonb),
  ('masquerade-party', 'MASQUERADE', 'Masquerade Party', 'A masked night with velvet, warm gold, a 360-degree video booth and a masked dance floor. Bring a mask and dress for an evening in black and gold.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#d9b76c","secondaryColor":"#251b30","surface":"dark","channels":["events"]}}'::jsonb),
  ('cowboy-night', 'Cowboy Night', 'Western Party', 'A Western gathering with ranch-style décor, a cowboy dress code and a dance floor after sundown. Horse riding is planned as a supervised activity, subject to venue and operator confirmation.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#ffc585","secondaryColor":"#432719","surface":"dark","channels":["events"]}}'::jsonb),
  ('super-party', 'SOBER PARTY', 'HOUSE 001 · Cairo', 'An alcohol- and drug-free house party built around sound, projection and play. The Frequency brings house, UK garage and baile funk to the dance floor. Explore The Portal, add to a UV mural in The Playground, or take a break at the alcohol-free bar. The Switch brings sound and visuals together in one coordinated takeover.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#d5ff3f","secondaryColor":"#241338","surface":"dark","channels":["events"]}}'::jsonb)
